const errorData = $input.first().json;
const execution = errorData.execution || {};
const workflow = errorData.workflow || {};
const error = execution.error || {};

const errorNode = error.node?.name || execution.lastNodeExecuted || 'Nieznany node';
const errorMessage = error.message || 'Brak szczegółów błędu';
const workflowName = workflow.name || 'Nieznany workflow';
const workflowId = workflow.id || 'N/A';
const executionId = execution.id || 'N/A';
const executionUrl = execution.url || '';
const timestamp = new Date().toISOString();

let severity = 'MEDIUM';
let emoji = '🟡';
if (errorMessage.includes('ECONNREFUSED') || errorMessage.includes('timeout') || errorMessage.includes('rate limit') || errorMessage.includes('503')) {
  severity = 'HIGH'; emoji = '🔴';
} else if (errorMessage.includes('parse') || errorMessage.includes('validation') || errorMessage.includes('FALLBACK')) {
  severity = 'LOW'; emoji = '🟠';
}

const slackMsg = `${emoji} *BŁĄD W AUTOMATYZACJI EMAIL*\n\n*Workflow:* ${workflowName} (${workflowId})\n*Execution:* ${executionId}\n*Node:* ${errorNode}\n*Czas:* ${timestamp}\n*Severity:* ${severity}\n\n*Błąd:*\n\`\`\`${errorMessage.substring(0, 800)}\`\`\`\n${severity === 'HIGH' ? '\n⚠️ *Wymagana natychmiastowa interwencja!*' : ''}\n${executionUrl ? '🔗 ' + executionUrl : ''}`;

const emailHtml = `<h2>${emoji} Błąd w automatyzacji email</h2><table style='border-collapse:collapse;'><tr><td style='padding:4px 12px;font-weight:bold;'>Workflow:</td><td>${workflowName} (${workflowId})</td></tr><tr><td style='padding:4px 12px;font-weight:bold;'>Execution:</td><td>${executionId}</td></tr><tr><td style='padding:4px 12px;font-weight:bold;'>Node:</td><td>${errorNode}</td></tr><tr><td style='padding:4px 12px;font-weight:bold;'>Czas:</td><td>${timestamp}</td></tr><tr><td style='padding:4px 12px;font-weight:bold;'>Severity:</td><td>${severity}</td></tr></table><pre style='background:#f5f5f5;padding:12px;border-radius:4px;'>${errorMessage.substring(0, 1000)}</pre>${executionUrl ? '<p><a href="' + executionUrl + '">Otwórz execution log</a></p>' : ''}`;

return [{ json: { slackMsg: slackMsg.substring(0, 3000), emailHtml, emailSubject: `${emoji} [${severity}] Błąd: ${errorNode} — ${workflowName}`, severity, errorNode, errorMessage, timestamp } }];
